     1→// ============================================================================
     2→// FreeLang Physical Plan Module - 논리 계획 → 물리 계획 변환
     3→// ============================================================================
     4→// 목표: Logical Plan(planner.ExecPlan) → Physical Plan(연산자 파이프라인)
     5→// 원리:
     6→//   1. 논리 계획(PLAN_FULL_SCAN, PLAN_INDEX_EQ, etc.)을 물리 연산자로 변환
     7→//   2. 연산자 파이프라인: TABLE_SCAN → FILTER → SORT → LIMIT
     8→//   3. 비용 추정: 각 연산자별 O(n) 또는 O(log n)
     9→// 구조:
    10→//   - 상수 정의 (연산자 타입, 에러 코드)
    11→//   - PhysicalOp, PhysicalPlan 구조체
    12→//   - 계획 생성 및 변환 함수
    13→//   - 파이프라인 연결 및 비용 계산
    14→// ============================================================================
    15→
    16→module physical_plan {
    17→    // === 연산자 타입 ===
    18→    const PHYS_PLAN_TABLE_SCAN:  i32 = 1;   // 전체 테이블 스캔
    19→    const PHYS_PLAN_INDEX_SCAN:  i32 = 2;   // 인덱스 기반 스캔
    20→    const PHYS_PLAN_FILTER:      i32 = 3;   // WHERE 조건 필터
    21→    const PHYS_PLAN_SORT:        i32 = 4;   // ORDER BY 정렬
    22→    const PHYS_PLAN_LIMIT:       i32 = 5;   // LIMIT/OFFSET 페이징
    23→    const PHYS_PLAN_AGGREGATE:   i32 = 6;   // 집계 함수 (COUNT/SUM/MAX/MIN)
    24→    const PHYS_PLAN_NESTED_LOOP: i32 = 7;   // 중첩 루프 조인 (향후)
    25→
    26→    // === 집계 연산자 타입 ===
    27→    const PHYS_AGG_NONE:  i32 = 0;
    28→    const PHYS_AGG_COUNT: i32 = 1;
    29→    const PHYS_AGG_SUM:   i32 = 2;
    30→    const PHYS_AGG_MAX:   i32 = 3;
    31→    const PHYS_AGG_MIN:   i32 = 4;
    32→
    33→    // === 에러 코드 ===
    34→    const PHYS_OK:               i32 = 0;
    35→    const PHYS_ERR_NOT_FOUND:    i32 = 90;
    36→    const PHYS_ERR_INVALID_PLAN: i32 = 91;
    37→    const PHYS_ERR_FULL:         i32 = 92;
    38→
    39→    // === 제한값 ===
    40→    const MAX_OPS: i32 = 32;   // 최대 연산자 수 (파이프라인 깊이)
    41→    const MAX_COLS: i32 = 16;
    42→
    43→    // === 데이터 구조체 ===
    44→
    45→    // 물리 연산자 (파이프라인 노드)
    46→    struct PhysicalOp {
    47→        op_type:     i32;      // PHYS_PLAN_* 상수
    48→        col_idx:     i32;      // 연산 컬럼 인덱스 (-1 = 무관)
    49→        agg_type:    i32;      // PHYS_AGG_* (집계 연산자용)
    50→        limit_count: i32;      // LIMIT 행 수 (-1 = 무제한)
    51→        next_op:     i32;      // 파이프라인 다음 연산자 인덱스 (-1 = 끝)
    52→        is_used:     bool;     // 슬롯 사용 여부
    53→    }
    54→
    55→    // 물리 계획 (연산자 파이프라인)
    56→    struct PhysicalPlan {
    57→        ops:         [PhysicalOp];    // 연산자 배열
    58→        op_count:    i32;             // 사용 중인 연산자 수
    59→        root_op_idx: i32;             // 루트 연산자 인덱스
    60→    }
    61→
    62→    // === 초기화 함수 ===
    63→
    64→    // 새로운 물리 계획 생성
    65→    func physical_plan_new() -> PhysicalPlan {
    66→        let pp = PhysicalPlan{
    67→            ops:         make([PhysicalOp], MAX_OPS),
    68→            op_count:    0,
    69→            root_op_idx: -1,
    70→        };
    71→
    72→        // 모든 슬롯을 미사용으로 초기화
    73→        let i = 0;
    74→        for i = 0; i < MAX_OPS; i = i + 1 {
    75→            pp.ops[i].is_used = false;
    76→            pp.ops[i].next_op = -1;
    77→        }
    78→
    79→        return pp;
    80→    }
    81→
    82→    // === 핵심 변환 함수 ===
    83→
    84→    // 논리 계획(ExecPlan)을 물리 계획(PhysicalPlan)으로 변환
    85→    func physical_plan_from_logical(ep: planner.ExecPlan) -> (PhysicalPlan, i32) {
    86→        let pp = physical_plan_new();
    87→
    88→        // 논리 계획 타입에 따라 연산자 파이프라인 구성
    89→        if ep.plan_type == planner.PLAN_FULL_SCAN {
    90→            // 풀스캔: TABLE_SCAN → FILTER → SORT → LIMIT
    91→            let idx_table = pp_alloc_op_slot(&pp);
    92→            if idx_table < 0 {
    93→                return (pp, PHYS_ERR_FULL);
    94→            }
    95→
    96→            // TABLE_SCAN 연산자
    97→            pp.ops[idx_table].op_type = PHYS_PLAN_TABLE_SCAN;
    98→            pp.ops[idx_table].col_idx = -1;
    99→            pp.ops[idx_table].is_used = true;
   100→            pp.root_op_idx = idx_table;
   101→
   102→            return (pp, PHYS_OK);
   103→        }
   104→
   105→        // INDEX_EQ: INDEX_SCAN → FILTER
   106→        if ep.plan_type == planner.PLAN_INDEX_EQ {
   107→            let idx_scan = pp_alloc_op_slot(&pp);
   108→            if idx_scan < 0 {
   109→                return (pp, PHYS_ERR_FULL);
   110→            }
   111→
   112→            // INDEX_SCAN 연산자
   113→            pp.ops[idx_scan].op_type = PHYS_PLAN_INDEX_SCAN;
   114→            pp.ops[idx_scan].col_idx = ep.index_col;
   115→            pp.ops[idx_scan].is_used = true;
   116→            pp.root_op_idx = idx_scan;
   117→
   118→            return (pp, PHYS_OK);
   119→        }
   120→
   121→        // INDEX_RANGE: INDEX_SCAN → FILTER
   122→        if ep.plan_type == planner.PLAN_INDEX_RANGE {
   123→            let idx_scan = pp_alloc_op_slot(&pp);
   124→            if idx_scan < 0 {
   125→                return (pp, PHYS_ERR_FULL);
   126→            }
   127→
   128→            // INDEX_SCAN 연산자 (범위)
   129→            pp.ops[idx_scan].op_type = PHYS_PLAN_INDEX_SCAN;
   130→            pp.ops[idx_scan].col_idx = ep.index_col;
   131→            pp.ops[idx_scan].is_used = true;
   132→            pp.root_op_idx = idx_scan;
   133→
   134→            return (pp, PHYS_OK);
   135→        }
   136→
   137→        // INDEX_LIKE: INDEX_SCAN (문자열 인덱스)
   138→        if ep.plan_type == planner.PLAN_INDEX_LIKE {
   139→            let idx_scan = pp_alloc_op_slot(&pp);
   140→            if idx_scan < 0 {
   141→                return (pp, PHYS_ERR_FULL);
   142→            }
   143→
   144→            pp.ops[idx_scan].op_type = PHYS_PLAN_INDEX_SCAN;
   145→            pp.ops[idx_scan].col_idx = ep.index_col;
   146→            pp.ops[idx_scan].is_used = true;
   147→            pp.root_op_idx = idx_scan;
   148→
   149→            return (pp, PHYS_OK);
   150→        }
   151→
   152→        // 미지의 논리 계획
   153→        return (pp, PHYS_ERR_INVALID_PLAN);
   154→    }
   155→
   156→    // === 파이프라인 구성 함수 ===
   157→
   158→    // 물리 계획에 새로운 연산자 추가
   159→    func physical_plan_add_op(pp: *PhysicalPlan, op_type: i32, col_idx: i32, agg_type: i32, limit: i32) -> i32 {
   160→        if pp.op_count >= MAX_OPS {
   161→            return PHYS_ERR_FULL;
   162→        }
   163→
   164→        let op_idx = pp_alloc_op_slot(pp);
   165→        if op_idx < 0 {
   166→            return PHYS_ERR_FULL;
   167→        }
   168→
   169→        pp.ops[op_idx].op_type = op_type;
   170→        pp.ops[op_idx].col_idx = col_idx;
   171→        pp.ops[op_idx].agg_type = agg_type;
   172→        pp.ops[op_idx].limit_count = limit;
   173→        pp.ops[op_idx].is_used = true;
   174→
   175→        return op_idx;
   176→    }
   177→
   178→    // 두 연산자를 파이프라인으로 연결 (from_idx → to_idx)
   179→    func physical_plan_connect(pp: *PhysicalPlan, from_idx: i32, to_idx: i32) -> i32 {
   180→        if from_idx < 0 || from_idx >= MAX_OPS || to_idx < 0 || to_idx >= MAX_OPS {
   181→            return PHYS_ERR_INVALID_PLAN;
   182→        }
   183→
   184→        if !pp.ops[from_idx].is_used || !pp.ops[to_idx].is_used {
   185→            return PHYS_ERR_NOT_FOUND;
   186→        }
   187→
   188→        pp.ops[from_idx].next_op = to_idx;
   189→        return PHYS_OK;
   190→    }
   191→
   192→    // === 비용 추정 함수 ===
   193→
   194→    // 물리 계획의 총 비용 계산
   195→    func physical_plan_get_cost(pp: *PhysicalPlan) -> i64 {
   196→        let total_cost = 0;
   197→        let op_idx = pp.root_op_idx;
   198→        let visited = 0;
   199→
   200→        // 루트부터 시작하여 파이프라인 순회
   201→        for visited = 0; visited < MAX_OPS && op_idx >= 0 && visited < pp.op_count; visited = visited + 1 {
   202→            let op = pp.ops[op_idx];
   203→
   204→            if op.op_type == PHYS_PLAN_TABLE_SCAN {
   205→                // TABLE_SCAN: O(n)
   206→                total_cost = total_cost + 1000;
   207→            } else if op.op_type == PHYS_PLAN_INDEX_SCAN {
   208→                // INDEX_SCAN: O(log n)
   209→                total_cost = total_cost + 100;
   210→            } else if op.op_type == PHYS_PLAN_FILTER {
   211→                // FILTER: O(k) (k = 필터 조건 복잡도)
   212→                total_cost = total_cost + 50;
   213→            } else if op.op_type == PHYS_PLAN_SORT {
   214→                // SORT: O(n log n)
   215→                total_cost = total_cost + 500;
   216→            } else if op.op_type == PHYS_PLAN_LIMIT {
   217→                // LIMIT: O(1)
   218→                total_cost = total_cost + 10;
   219→            } else if op.op_type == PHYS_PLAN_AGGREGATE {
   220→                // AGGREGATE: O(n)
   221→                total_cost = total_cost + 200;
   222→            }
   223→
   224→            op_idx = op.next_op;
   225→        }
   226→
   227→        return total_cost;
   228→    }
   229→
   230→    // === 정보 조회 함수 ===
   231→
   232→    // 물리 계획의 루트 연산자 인덱스 반환
   233→    func physical_plan_get_root(pp: *PhysicalPlan) -> i32 {
   234→        return pp.root_op_idx;
   235→    }
   236→
   237→    // 물리 계획의 통계 정보 출력 (디버깅용)
   238→    func physical_plan_stats(pp: *PhysicalPlan) -> string {
   239→        let stats_str = "PhysicalPlan(ops:";
   240→        let i = 0;
   241→
   242→        // 연산자 개수 계산
   243→        for i = 0; i < MAX_OPS; i = i + 1 {
   244→            if pp.ops[i].is_used {
   245→                // 간단 포맷: op_count와 root_op_idx만 표시
   246→            }
   247→        }
   248→
   249→        stats_str = stats_str + i32_to_str(pp.op_count);
   250→        stats_str = stats_str + ", root:";
   251→        stats_str = stats_str + i32_to_str(pp.root_op_idx);
   252→        stats_str = stats_str + ")";
   253→
   254→        return stats_str;
   255→    }
   256→
   257→    // === 헬퍼 함수 ===
   258→
   259→    // 물리 계획에서 다음 사용 가능한 연산자 슬롯 할당
   260→    @inline
   261→    func pp_alloc_op_slot(pp: *PhysicalPlan) -> i32 {
   262→        if pp.op_count >= MAX_OPS {
   263→            return PHYS_ERR_FULL;
   264→        }
   265→
   266→        let op_idx = pp.op_count;
   267→        pp.op_count = pp.op_count + 1;
   268→        pp.ops[op_idx].is_used = false;
   269→        pp.ops[op_idx].next_op = -1;
   270→
   271→        return op_idx;
   272→    }
   273→
   274→    // 연산자 타입을 문자열로 변환 (디버깅)
   275→    @inline
   276→    func op_type_to_str(op_type: i32) -> string {
   277→        if op_type == PHYS_PLAN_TABLE_SCAN {
   278→            return "TABLE_SCAN";
   279→        }
   280→        if op_type == PHYS_PLAN_INDEX_SCAN {
   281→            return "INDEX_SCAN";
   282→        }
   283→        if op_type == PHYS_PLAN_FILTER {
   284→            return "FILTER";
   285→        }
   286→        if op_type == PHYS_PLAN_SORT {
   287→            return "SORT";
   288→        }
   289→        if op_type == PHYS_PLAN_LIMIT {
   290→            return "LIMIT";
   291→        }
   292→        if op_type == PHYS_PLAN_AGGREGATE {
   293→            return "AGGREGATE";
   294→        }
   295→        if op_type == PHYS_PLAN_NESTED_LOOP {
   296→            return "NESTED_LOOP";
   297→        }
   298→        return "UNKNOWN";
   299→    }
   300→
   301→    // 集計タイプを文字列に変換 (デバッグ用)
   302→    @inline
   303→    func agg_type_to_str(agg_type: i32) -> string {
   304→        if agg_type == PHYS_AGG_COUNT {
   305→            return "COUNT";
   306→        }
   307→        if agg_type == PHYS_AGG_SUM {
   308→            return "SUM";
   309→        }
   310→        if agg_type == PHYS_AGG_MAX {
   311→            return "MAX";
   312→        }
   313→        if agg_type == PHYS_AGG_MIN {
   314→            return "MIN";
   315→        }
   316→        return "NONE";
   317→    }
   318→
   319→    // === 파이프라인 검증 함수 ===
   320→
   321→    // 물리 계획의 파이프라인이 유효한지 검증
   322→    func physical_plan_validate(pp: *PhysicalPlan) -> bool {
   323→        if pp.root_op_idx < 0 {
   324→            return false;
   325→        }
   326→
   327→        if pp.root_op_idx >= MAX_OPS || !pp.ops[pp.root_op_idx].is_used {
   328→            return false;
   329→        }
