   375→        let op_idx = pp.root_op_idx;
   376→        let visited = 0;
   377→
   378→        for visited = 0; visited < MAX_OPS && op_idx >= 0; visited = visited + 1 {
   379→            if pp.ops[op_idx].op_type == op_type {
   380→                return true;
   381→            }
   382→
   383→            op_idx = pp.ops[op_idx].next_op;
   384→        }
   385→
   386→        return false;
   387→    }
