// ============================================================================
// FreeLang Executor 통합 테스트 - Phase 9 (Query Executor Engine)
// ============================================================================
// 범위: executor 모듈의 3가지 통합 테스트
// 시나리오:
//   1. test_executor_table_scan: TABLE_SCAN만 실행
//   2. test_executor_filter: TABLE_SCAN → FILTER 파이프라인
//   3. test_executor_sort_limit: TABLE_SCAN → SORT → LIMIT 파이프라인
// ============================================================================

module executor_test {
    // === 테스트 유틸리티 ===

    struct TestResult {
        name:    string;
        passed:  bool;
        message: string;
    }

    func assert_true(condition: bool, name: string) -> TestResult {
        return TestResult{
            name:    name,
            passed:  condition,
            message: if condition { "PASS" } else { "FAIL" },
        };
    }

    func assert_eq_i32(actual: i32, expected: i32, name: string) -> TestResult {
        let passed = actual == expected;
        return TestResult{
            name:    name,
            passed:  passed,
            message: if passed { "PASS" } else { "FAIL: expected " + i32_to_str(expected) + " got " + i32_to_str(actual) },
        };
    }

    func assert_ge_i32(actual: i32, expected: i32, name: string) -> TestResult {
        let passed = actual >= expected;
        return TestResult{
            name:    name,
            passed:  passed,
            message: if passed { "PASS" } else { "FAIL: expected >= " + i32_to_str(expected) + " got " + i32_to_str(actual) },
        };
    }

    func print_result(r: TestResult) {
        let status = if r.passed { "[PASS]" } else { "[FAIL]" };
        print(status + " " + r.name + " - " + r.message);
    }

    // === 헬퍼 함수 ===

    // 테이블 생성 및 컬럼 정의 (id, age 두 컬럼)
    func create_test_table() -> schema.Table {
        let table = schema.table_new();
        let s = schema.schema_new("test_table");
        s.schema_add_col("id", schema.COL_TYPE_INT, false);
        s.schema_add_col("age", schema.COL_TYPE_INT, false);
        table.schema = s;
        table.int_cols = make([i64], schema.MAX_COLS * schema.MAX_ROWS);
        table.str_cols = make([string], schema.MAX_COLS * schema.MAX_ROWS);
        table.bool_cols = make([bool], schema.MAX_COLS * schema.MAX_ROWS);
        table.deleted_flags = make([bool], schema.MAX_ROWS);
        table.row_ids = make([i64], schema.MAX_ROWS);
        table.row_count = 0;
        table.next_id = 1;
        return table;
    }

    // 테이블에 행 삽입 (id, age)
    func insert_row(table: *schema.Table, id: i64, age: i64) -> i32 {
        if table.row_count >= schema.MAX_ROWS {
            return schema.SCHEMA_ERR_FULL;
        }

        let row_idx = table.row_count;

        // id 컬럼 (인덱스 0)
        table.int_cols[0 * schema.MAX_ROWS + row_idx] = id;
        // age 컬럼 (인덱스 1)
        table.int_cols[1 * schema.MAX_ROWS + row_idx] = age;

        table.row_ids[row_idx] = table.next_id;
        table.deleted_flags[row_idx] = false;
        table.next_id = table.next_id + 1;
        table.row_count = table.row_count + 1;

        return schema.SCHEMA_OK;
    }

    // 테이블에서 행 읽기
    func read_row(table: *schema.Table, row_idx: i32) -> (i64, i64) {
        let id = table.int_cols[0 * schema.MAX_ROWS + row_idx];
        let age = table.int_cols[1 * schema.MAX_ROWS + row_idx];
        return (id, age);
    }

    // === 테스트 케이스 ===

    // 테스트 1: test_executor_table_scan
    // 기능: TABLE_SCAN만 실행, 모든 행 반환
    // 검증: result.row_count == 10
    func test_executor_table_scan() -> TestResult {
        let table = create_test_table();

        // 10개 행 삽입 (id=1-10, age=20-29)
        let i = 0;
        for i = 0; i < 10; i = i + 1 {
            insert_row(&table, i64_from_i32(i + 1), i64_from_i32(i + 20));
        }

        // executor 생성 및 초기화
        let exec = executor.executor_new();
        let result = executor.executor_execute(&exec, &table);

        // 검증: 10개 행이 모두 반환되었는지 확인
        return assert_eq_i32(result.row_count, 10, "test_executor_table_scan");
    }

    // 테스트 2: test_executor_filter
    // 기능: TABLE_SCAN → FILTER(age > 10) 파이프라인
    // 검증: age > 10인 행만 반환 (10개)
    func test_executor_filter() -> TestResult {
        let table = create_test_table();

        // 20개 행 삽입 (age=1-20)
        let i = 0;
        for i = 0; i < 20; i = i + 1 {
            insert_row(&table, i64_from_i32(i + 1), i64_from_i32(i + 1));
        }

        // executor 생성 및 필터 조건 설정 (age > 10)
        let exec = executor.executor_new();
        executor.executor_set_filter(&exec, 1, executor.FILTER_GT, 10);
        let result = executor.executor_execute(&exec, &table);

        // 검증 1: age > 10인 행이 10개 있는지 확인
        let test1 = assert_eq_i32(result.row_count, 10, "test_executor_filter: row_count");

        // 검증 2: 첫 번째 행의 age >= 11인지 확인
        if result.row_count > 0 {
            let first_age = result.rows[0 * schema.MAX_COLS + 1];
            let test2 = assert_ge_i32(i32_from_i64(first_age), 11, "test_executor_filter: first_row_age");
            if !test1.passed {
                return test1;
            }
            return test2;
        }

        return test1;
    }

    // 테스트 3: test_executor_sort_limit
    // 기능: TABLE_SCAN → SORT(score ASC) → LIMIT(5) 파이프라인
    // 검증:
    //   - row_count == 5
    //   - 첫 번째 행이 최솟값(1)
    //   - 다섯 번째 행이 최댓값(5)
    func test_executor_sort_limit() -> TestResult {
        let table = create_test_table();

        // 15개 행 삽입 (score 역순: 15,14,13,...,1)
        let i = 0;
        for i = 0; i < 15; i = i + 1 {
            let score = i64_from_i32(15 - i);
            insert_row(&table, i64_from_i32(i + 1), score);
        }

        // executor 생성 및 SORT+LIMIT 설정
        let exec = executor.executor_new();
        executor.executor_set_sort(&exec, 1, executor.SORT_ASC);
        executor.executor_set_limit(&exec, 5);
        let result = executor.executor_execute(&exec, &table);

        // 검증 1: row_count == 5
        let test1 = assert_eq_i32(result.row_count, 5, "test_executor_sort_limit: row_count");

        if !test1.passed {
            return test1;
        }

        // 검증 2: 첫 번째 행의 score = 1 (최솟값)
        let first_score = result.rows[0 * schema.MAX_COLS + 1];
        let test2 = assert_eq_i32(i32_from_i64(first_score), 1, "test_executor_sort_limit: first_row");

        if !test2.passed {
            return test2;
        }

        // 검증 3: 다섯 번째 행의 score = 5 (최댓값)
        let last_score = result.rows[4 * schema.MAX_COLS + 1];
        return assert_eq_i32(i32_from_i64(last_score), 5, "test_executor_sort_limit: last_row");
    }

