executor_code = """// ============================================================================
// FreeLang Executor Module - 물리 계획 실행 엔진
// ============================================================================
// 목표: Physical Plan을 기반으로 테이블 데이터 실행 및 결과 반환
// 원리:
//   1. Executor: 필터, 정렬, 제한 조건을 관리하는 상태 머신
//   2. Pipeline: TABLE_SCAN → FILTER → SORT → LIMIT 순차 처리
//   3. Result: 플래튼화된 결과 행 배열 (재사용성을 위해)
// 구조:
//   - 상수 정의 (에러 코드, 연산자 타입)
//   - Executor, ExecutorResult 구조체
//   - 초기화 및 설정 함수
//   - 핵심 실행 함수
// ============================================================================

module executor {
    // === 에러 코드 ===
    const EXEC_OK:                i32 = 0;
    const EXEC_ERR_INVALID_OP:    i32 = 100;
    const EXEC_ERR_FULL:          i32 = 101;
    const EXEC_ERR_TYPE_MISMATCH: i32 = 102;

    // === 필터 연산자 타입 ===
    const FILTER_EQ:  i32 = 1;
    const FILTER_GT:  i32 = 2;
    const FILTER_LT:  i32 = 3;
    const FILTER_GE:  i32 = 4;
    const FILTER_LE:  i32 = 5;
    const FILTER_NE:  i32 = 6;

    // === 정렬 연산자 타입 ===
    const SORT_ASC:   i32 = 1;
    const SORT_DESC:  i32 = 2;

    // === 제한값 ===
    const MAX_RESULT_ROWS: i32 = 1024;

    // === 데이터 구조체 ===

    // 실행 결과
    struct ExecutorResult {
        row_count:   i32;                          // 반환된 행 수
        rows:        [i64];                        // 결과 행 배열 (플래튼화)
        error_code:  i32;                          // 에러 코드
    }

    // Executor (파이프라인 상태 머신)
    struct Executor {
        // 필터 상태
        has_filter:  bool;
        filter_col:  i32;
        filter_op:   i32;
        filter_val:  i64;

        // 정렬 상태
        has_sort:    bool;
        sort_col:    i32;
        sort_order:  i32;

        // 제한 상태
        has_limit:   bool;
        limit_count: i32;
    }

    // === 초기화 함수 ===

    // 새로운 Executor 생성
    func executor_new() -> Executor {
        return Executor{
            has_filter:   false,
            filter_col:   -1,
            filter_op:    FILTER_EQ,
            filter_val:   0,
            has_sort:     false,
            sort_col:     -1,
            sort_order:   SORT_ASC,
            has_limit:    false,
            limit_count:  -1,
        };
    }

    // === 설정 함수 ===

    // 필터 조건 설정
    func executor_set_filter(ex: *Executor, col_idx: i32, op: i32, val: i64) {
        if col_idx < 0 || op < FILTER_EQ || op > FILTER_NE {
            return;
        }

        ex.has_filter = true;
        ex.filter_col = col_idx;
        ex.filter_op = op;
        ex.filter_val = val;
    }

    // 정렬 조건 설정
    func executor_set_sort(ex: *Executor, col_idx: i32, order: i32) {
        if col_idx < 0 || (order != SORT_ASC && order != SORT_DESC) {
            return;
        }

        ex.has_sort = true;
        ex.sort_col = col_idx;
        ex.sort_order = order;
    }

    // 제한 조건 설정
    func executor_set_limit(ex: *Executor, limit_count: i32) {
        if limit_count <= 0 {
            return;
        }

        ex.has_limit = true;
        ex.limit_count = limit_count;
    }

    // === 핵심 실행 함수 ===

    // TABLE_SCAN 단계: 모든 행 읽기 (삭제 표시 제외)
    func exec_table_scan(table: *schema.Table) -> ExecutorResult {
        let result = ExecutorResult{
            row_count:   0,
            rows:        make([i64], schema.MAX_COLS * MAX_RESULT_ROWS),
            error_code:  EXEC_OK,
        };

        if table.row_count > MAX_RESULT_ROWS {
            result.error_code = EXEC_ERR_FULL;
            return result;
        }

        // 삭제되지 않은 모든 행 복사
        let row_idx = 0;
        for row_idx = 0; row_idx < table.row_count; row_idx = row_idx + 1 {
            if !table.deleted_flags[row_idx] {
                // 각 컬럼 복사
                let col_idx = 0;
                for col_idx = 0; col_idx < table.schema.col_count; col_idx = col_idx + 1 {
                    let src_pos = col_idx * schema.MAX_ROWS + row_idx;
                    let dst_pos = col_idx * MAX_RESULT_ROWS + result.row_count;
                    result.rows[dst_pos] = table.int_cols[src_pos];
                }
                result.row_count = result.row_count + 1;
            }
        }

        return result;
    }

    // FILTER 단계: 조건 평가 후 행 필터링
    func exec_filter(result: *ExecutorResult, ex: *Executor) -> i32 {
        if !ex.has_filter {
            return EXEC_OK;
        }

        let filtered_count = 0;
        let row_idx = 0;

        for row_idx = 0; row_idx < result.row_count; row_idx = row_idx + 1 {
            let filter_col_pos = ex.filter_col * MAX_RESULT_ROWS + row_idx;
            let col_val = result.rows[filter_col_pos];

            // 필터 조건 평가
            let pass = false;
            if ex.filter_op == FILTER_EQ {
                pass = col_val == ex.filter_val;
            } else if ex.filter_op == FILTER_GT {
                pass = col_val > ex.filter_val;
            } else if ex.filter_op == FILTER_LT {
                pass = col_val < ex.filter_val;
            } else if ex.filter_op == FILTER_GE {
                pass = col_val >= ex.filter_val;
            } else if ex.filter_op == FILTER_LE {
                pass = col_val <= ex.filter_val;
            } else if ex.filter_op == FILTER_NE {
                pass = col_val != ex.filter_val;
            }

            // 통과한 행 복사
            if pass {
                let col_idx = 0;
                for col_idx = 0; col_idx < schema.MAX_COLS; col_idx = col_idx + 1 {
                    let src_pos = col_idx * MAX_RESULT_ROWS + row_idx;
                    let dst_pos = col_idx * MAX_RESULT_ROWS + filtered_count;
                    result.rows[dst_pos] = result.rows[src_pos];
                }
                filtered_count = filtered_count + 1;
            }
        }

        result.row_count = filtered_count;
        return EXEC_OK;
    }

    // SORT 단계: 행 정렬 (버블 소트, O(n^2))
    func exec_sort(result: *ExecutorResult, ex: *Executor) -> i32 {
        if !ex.has_sort || result.row_count <= 1 {
            return EXEC_OK;
        }

        let i = 0;
        let j = 0;

        // 버블 소트
        for i = 0; i < result.row_count - 1; i = i + 1 {
            for j = 0; j < result.row_count - i - 1; j = j + 1 {
                let pos1 = ex.sort_col * MAX_RESULT_ROWS + j;
                let pos2 = ex.sort_col * MAX_RESULT_ROWS + (j + 1);

                let val1 = result.rows[pos1];
                let val2 = result.rows[pos2];

                // 정렬 순서 결정
                let should_swap = false;
                if ex.sort_order == SORT_ASC {
                    should_swap = val1 > val2;
                } else {
                    should_swap = val1 < val2;
                }

                // 행 교환
                if should_swap {
                    let col_idx = 0;
                    for col_idx = 0; col_idx < schema.MAX_COLS; col_idx = col_idx + 1 {
                        let p1 = col_idx * MAX_RESULT_ROWS + j;
                        let p2 = col_idx * MAX_RESULT_ROWS + (j + 1);

                        let temp = result.rows[p1];
                        result.rows[p1] = result.rows[p2];
                        result.rows[p2] = temp;
                    }
                }
            }
        }

        return EXEC_OK;
    }

    // LIMIT 단계: 행 수 제한
    func exec_limit(result: *ExecutorResult, ex: *Executor) -> i32 {
        if !ex.has_limit {
            return EXEC_OK;
        }

        if ex.limit_count < result.row_count {
            result.row_count = ex.limit_count;
        }

        return EXEC_OK;
    }

    // === 메인 실행 함수 ===

    // 전체 파이프라인 실행: TABLE_SCAN → FILTER → SORT → LIMIT
    func executor_execute(ex: *Executor, table: *schema.Table) -> ExecutorResult {
        // Step 1: TABLE_SCAN
        let result = exec_table_scan(table);
        if result.error_code != EXEC_OK {
            return result;
        }

        // Step 2: FILTER (선택적)
        if ex.has_filter {
            let err = exec_filter(&result, ex);
            if err != EXEC_OK {
                result.error_code = err;
                return result;
            }
        }

        // Step 3: SORT (선택적)
        if ex.has_sort {
            let err = exec_sort(&result, ex);
            if err != EXEC_OK {
                result.error_code = err;
                return result;
            }
        }

        // Step 4: LIMIT (선택적)
        if ex.has_limit {
            let err = exec_limit(&result, ex);
            if err != EXEC_OK {
                result.error_code = err;
                return result;
            }
        }

        result.error_code = EXEC_OK;
        return result;
    }

    // === 정보 조회 함수 ===

    // Executor의 현재 상태를 문자열로 반환
    func executor_stats(ex: *Executor) -> string {
        let stats = "Executor(";

        if ex.has_filter {
            stats = stats + "FILTER(col=" + i32_to_str(ex.filter_col);
            stats = stats + " op=" + i32_to_str(ex.filter_op);
            stats = stats + ") ";
        }

        if ex.has_sort {
            stats = stats + "SORT(col=" + i32_to_str(ex.sort_col);
            stats = stats + " order=" + i32_to_str(ex.sort_order);
            stats = stats + ") ";
        }

        if ex.has_limit {
            stats = stats + "LIMIT(" + i32_to_str(ex.limit_count) + ")";
        }

        stats = stats + ")";
        return stats;
    }
}

// === 사용 예시 ===
//
// 1. TABLE_SCAN만 실행:
//    let ex = executor.executor_new();
//    let result = executor.executor_execute(&ex, &table);
//    print(i32_to_str(result.row_count) + " rows");
//
// 2. FILTER 적용:
//    let ex = executor.executor_new();
//    executor.executor_set_filter(&ex, 1, executor.FILTER_GT, 10);
//    let result = executor.executor_execute(&ex, &table);
//
// 3. SORT + LIMIT 적용:
//    let ex = executor.executor_new();
//    executor.executor_set_sort(&ex, 1, executor.SORT_ASC);
//    executor.executor_set_limit(&ex, 5);
//    let result = executor.executor_execute(&ex, &table);
//
"""

